#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int rounds;
    cin >> rounds;
    vector<int> alice(rounds), bob(rounds);
    for (int i = 0; i < rounds; ++i) cin >> alice[i];
    for (int i = 0; i < rounds; ++i) cin >> bob[i];

    vector<int> bob_shifted(bob.begin() + 1, bob.end());
    bob_shifted.push_back(bob[0]);

    int min_win = 0, max_win = 0;
    for (int i = 0; i < rounds; ++i) {
        max_win += min(alice[i], bob_shifted[i]);
    }

    int max_bob = *max_element(bob_shifted.begin(), bob_shifted.end());
    for (int i = 0; i < rounds; ++i) {
        if (bob_shifted[i] == max_bob && bob_shifted[i] + alice[i] > min_win) {
            min_win = bob_shifted[i] + alice[i];
        }
    }

    int max_alice = *max_element(alice.begin(), alice.end());
    for (int i = 0; i < rounds; ++i) {
        if (alice[i] == max_alice && alice[i] + bob_shifted[i] > min_win) {
            min_win = alice[i] + bob_shifted[i];
        }
    }

    if (min_win > rounds) min_win -= rounds;
    else min_win = 0;

    cout << min_win << " " << max_win << "\n";

    return 0;
}
